-- Portable SQL: ISO-8601 UTC TEXT timestamps and date-only YYYY-MM-DD values.
-- PostgreSQL and SQLite share the same constraints; no user content is interpolated.
CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE memberships (workspace_id TEXT NOT NULL REFERENCES workspaces(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('owner','admin','member','viewer')), PRIMARY KEY(workspace_id,user_id));
CREATE TABLE teams (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), key TEXT NOT NULL, name TEXT NOT NULL, next_number INTEGER NOT NULL DEFAULT 1 CHECK(next_number>0), UNIQUE(workspace_id,id), UNIQUE(workspace_id,key));
CREATE TABLE statuses (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, team_id TEXT NOT NULL, name TEXT NOT NULL, category TEXT NOT NULL CHECK(category IN ('triage','backlog','unstarted','started','completed','canceled')), color TEXT NOT NULL, position REAL NOT NULL, UNIQUE(workspace_id,id), UNIQUE(workspace_id,team_id,id), UNIQUE(team_id,name), FOREIGN KEY(workspace_id,team_id) REFERENCES teams(workspace_id,id));
CREATE TABLE labels (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), name TEXT NOT NULL, color TEXT NOT NULL, UNIQUE(workspace_id,id), UNIQUE(workspace_id,name));
CREATE TABLE projects (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','in_progress','paused','completed','canceled')), health TEXT NOT NULL DEFAULT 'on_track' CHECK(health IN ('on_track','at_risk','off_track')), lead_id TEXT, start_date TEXT, target_date TEXT, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,lead_id) REFERENCES memberships(workspace_id,user_id), CHECK(start_date IS NULL OR target_date IS NULL OR start_date<=target_date));
CREATE TABLE project_teams (workspace_id TEXT NOT NULL, project_id TEXT NOT NULL, team_id TEXT NOT NULL, PRIMARY KEY(project_id,team_id), FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id), FOREIGN KEY(workspace_id,team_id) REFERENCES teams(workspace_id,id));
CREATE TABLE milestones (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, project_id TEXT NOT NULL, name TEXT NOT NULL, target_date TEXT, position REAL NOT NULL DEFAULT 0, UNIQUE(workspace_id,id), UNIQUE(workspace_id,project_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id));
CREATE TABLE cycles (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, team_id TEXT NOT NULL, name TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, UNIQUE(workspace_id,id), UNIQUE(workspace_id,team_id,id), FOREIGN KEY(workspace_id,team_id) REFERENCES teams(workspace_id,id), CHECK(start_date<=end_date));
CREATE TABLE issues (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, team_id TEXT NOT NULL, number INTEGER NOT NULL, key TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL DEFAULT 'issue' CHECK(kind IN ('issue','epic')), status_id TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 0 CHECK(priority BETWEEN 0 AND 4), assignee_id TEXT, creator_id TEXT NOT NULL, project_id TEXT, cycle_id TEXT, milestone_id TEXT, parent_id TEXT, estimate REAL CHECK(estimate IS NULL OR estimate>=0), start_date TEXT, due_date TEXT, position REAL NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT, deleted_at TEXT, UNIQUE(workspace_id,id), UNIQUE(workspace_id,key), UNIQUE(team_id,number), FOREIGN KEY(workspace_id,team_id) REFERENCES teams(workspace_id,id), FOREIGN KEY(workspace_id,team_id,status_id) REFERENCES statuses(workspace_id,team_id,id), FOREIGN KEY(workspace_id,assignee_id) REFERENCES memberships(workspace_id,user_id), FOREIGN KEY(workspace_id,creator_id) REFERENCES memberships(workspace_id,user_id), FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id), FOREIGN KEY(workspace_id,team_id,cycle_id) REFERENCES cycles(workspace_id,team_id,id), FOREIGN KEY(workspace_id,project_id,milestone_id) REFERENCES milestones(workspace_id,project_id,id), FOREIGN KEY(workspace_id,parent_id) REFERENCES issues(workspace_id,id), CHECK(parent_id IS NULL OR parent_id<>id), CHECK(start_date IS NULL OR due_date IS NULL OR start_date<=due_date));
CREATE INDEX issues_workspace_updated ON issues(workspace_id,updated_at,id);
CREATE INDEX issues_team_status ON issues(workspace_id,team_id,status_id,position);
CREATE INDEX issues_assignee ON issues(workspace_id,assignee_id);
CREATE INDEX issues_project ON issues(workspace_id,project_id);
CREATE INDEX issues_parent ON issues(workspace_id,parent_id);
CREATE TABLE issue_labels (workspace_id TEXT NOT NULL, issue_id TEXT NOT NULL, label_id TEXT NOT NULL, PRIMARY KEY(issue_id,label_id), FOREIGN KEY(workspace_id,issue_id) REFERENCES issues(workspace_id,id), FOREIGN KEY(workspace_id,label_id) REFERENCES labels(workspace_id,id));
CREATE INDEX issue_labels_label ON issue_labels(workspace_id,label_id);
CREATE TABLE relations (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, source_id TEXT NOT NULL, target_id TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('blocks','related','duplicates')), UNIQUE(workspace_id,source_id,target_id,type), CHECK(source_id<>target_id), FOREIGN KEY(workspace_id,source_id) REFERENCES issues(workspace_id,id), FOREIGN KEY(workspace_id,target_id) REFERENCES issues(workspace_id,id));
CREATE TABLE comments (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, issue_id TEXT NOT NULL, author_id TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(workspace_id,issue_id) REFERENCES issues(workspace_id,id), FOREIGN KEY(workspace_id,author_id) REFERENCES memberships(workspace_id,user_id));
CREATE INDEX comments_issue ON comments(workspace_id,issue_id,created_at);
CREATE TABLE activity (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, issue_id TEXT NOT NULL, actor_id TEXT NOT NULL, action TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(workspace_id,issue_id) REFERENCES issues(workspace_id,id), FOREIGN KEY(workspace_id,actor_id) REFERENCES memberships(workspace_id,user_id));
CREATE INDEX activity_issue ON activity(workspace_id,issue_id,created_at);
CREATE TABLE subscriptions (workspace_id TEXT NOT NULL, issue_id TEXT NOT NULL, user_id TEXT NOT NULL, PRIMARY KEY(issue_id,user_id), FOREIGN KEY(workspace_id,issue_id) REFERENCES issues(workspace_id,id), FOREIGN KEY(workspace_id,user_id) REFERENCES memberships(workspace_id,user_id));
CREATE TABLE notifications (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, user_id TEXT NOT NULL, issue_id TEXT NOT NULL, body TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL, FOREIGN KEY(workspace_id,issue_id) REFERENCES issues(workspace_id,id), FOREIGN KEY(workspace_id,user_id) REFERENCES memberships(workspace_id,user_id));
CREATE INDEX notifications_user ON notifications(workspace_id,user_id,read_at,created_at);
CREATE TABLE sessions (hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), workspace_id TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(workspace_id,user_id) REFERENCES memberships(workspace_id,user_id));
CREATE TABLE api_tokens (id TEXT PRIMARY KEY, hash TEXT NOT NULL UNIQUE, name TEXT NOT NULL, user_id TEXT NOT NULL, workspace_id TEXT NOT NULL, scopes TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(workspace_id,user_id) REFERENCES memberships(workspace_id,user_id));
CREATE TABLE invitations (id TEXT PRIMARY KEY, hash TEXT NOT NULL UNIQUE, workspace_id TEXT NOT NULL REFERENCES workspaces(id), email TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','member','viewer')), expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE module_settings (workspace_id TEXT NOT NULL REFERENCES workspaces(id), module TEXT NOT NULL, enabled INTEGER NOT NULL CHECK(enabled IN (0,1)), config TEXT NOT NULL DEFAULT '{}', PRIMARY KEY(workspace_id,module));
CREATE TABLE saved_views (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, owner_id TEXT NOT NULL, name TEXT NOT NULL, filters TEXT NOT NULL, shared INTEGER NOT NULL DEFAULT 0 CHECK(shared IN (0,1)), created_at TEXT NOT NULL, FOREIGN KEY(workspace_id,owner_id) REFERENCES memberships(workspace_id,user_id));
CREATE TABLE attachments (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, issue_id TEXT NOT NULL, owner_id TEXT NOT NULL, object_key TEXT NOT NULL UNIQUE, filename TEXT NOT NULL, mime TEXT NOT NULL, bytes INTEGER NOT NULL CHECK(bytes>0), status TEXT NOT NULL CHECK(status IN ('pending','ready','rejected')), created_at TEXT NOT NULL, FOREIGN KEY(workspace_id,issue_id) REFERENCES issues(workspace_id,id), FOREIGN KEY(workspace_id,owner_id) REFERENCES memberships(workspace_id,user_id));
CREATE INDEX attachments_workspace ON attachments(workspace_id,status);
CREATE TABLE external_links (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, issue_id TEXT NOT NULL, provider TEXT NOT NULL, external_id TEXT NOT NULL, url TEXT NOT NULL, title TEXT NOT NULL, UNIQUE(workspace_id,provider,external_id,issue_id), FOREIGN KEY(workspace_id,issue_id) REFERENCES issues(workspace_id,id));
CREATE TABLE webhook_deliveries (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), provider TEXT NOT NULL, delivery_id TEXT NOT NULL, payload TEXT NOT NULL, event TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL, last_error TEXT, created_at TEXT NOT NULL, UNIQUE(workspace_id,provider,delivery_id));
CREATE INDEX deliveries_pending ON webhook_deliveries(status,next_attempt_at);
CREATE TABLE outbox (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), provider TEXT NOT NULL, event TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL, last_error TEXT, created_at TEXT NOT NULL);
CREATE INDEX outbox_pending ON outbox(status,next_attempt_at);
CREATE TABLE auth_attempts (key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, window_start TEXT NOT NULL);
CREATE TABLE idempotency_keys (workspace_id TEXT NOT NULL, user_id TEXT NOT NULL, key TEXT NOT NULL, request_hash TEXT NOT NULL, response TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(workspace_id,user_id,key), FOREIGN KEY(workspace_id,user_id) REFERENCES memberships(workspace_id,user_id));
